"use server";

// Generated by philote from page /clients/new. Do not edit.
import { redirect } from "next/navigation";

import { clients } from "@/lib/api";
import { type FormState, failed, text } from "@/lib/form";

export async function submit(_state: FormState, data: FormData): Promise<FormState> {
    const result = await clients.create({
        name: text(data, "name"),
        email: text(data, "email"),
        phone: text(data, "phone"),
    });
    if (!result.ok) {
        return failed(data, result.error, result.issues);
    }
    redirect("/pick");
}
